with unpacked as (select id, customer_id, ship_to, attributes, array_max(transform(items, x -> x.price)) as max_item_price, transform(items, x -> x.product_id) as product_ids, coalesce(ship_to.city, 'UNKNOWN') as city_or_unknown from carts) select id, customer_id, max_item_price, city_or_unknown, sum(max_item_price) over (partition by customer_id order by max_item_price, id rows between unbounded preceding and current row) as running_sum_max_item_price, min(max_item_price) over (partition by customer_id order by max_item_price, id rows between unbounded preceding and current row) as running_min_max_item_price, max(max_item_price) over (partition by customer_id order by max_item_price, id rows between unbounded preceding and current row) as running_max_max_item_price, avg(max_item_price) over (partition by customer_id order by max_item_price, id rows between unbounded preceding and current row) as running_avg_max_item_price, sum(max_item_price) over (order by max_item_price, id rows between unbounded preceding and current row) as cumulative_max_item_price from unpacked
